      const current = m ? m[1] : null;
      if (!current) return;
      return caches.open(CACHE_NAME).then(cache =>
        cache.keys().then(requests =>
          Promise.all(
            requests
              .filter(req => {
                const p = new URL(req.url).pathname;
                return /\/assets\/index-[^/]*\.js$/.test(p) && !p.endsWith('/' + current);
              })
              .map(req => cache.delete(req))
          )
        )
      );
